const WebSocket = require('ws');
const { spawn } = require('child_process');

const port = 18081;
const server = spawn(process.execPath, ['server.js'], {
  env: { ...process.env, COLLAB_PORT: String(port), COLLAB_HOST: '127.0.0.1' },
  stdio: ['ignore', 'pipe', 'pipe']
});

let serverLog = '';
server.stdout.on('data', chunk => { serverLog += chunk; });
server.stderr.on('data', chunk => { serverLog += chunk; });

const fail = (message) => {
  console.error(message);
  server.kill('SIGTERM');
  process.exit(1);
};

function checkEcho(clientName, messages) {
  return new Promise((resolve, reject) => {
    const socket = new WebSocket(`ws://127.0.0.1:${port}`);
    const received = [];
    socket.on('open', () => messages.forEach(message => socket.send(message)));
    socket.on('message', data => {
      received.push(data.toString());
      if (received.length === messages.length) {
        socket.close();
        resolve(received);
      }
    });
    socket.on('error', reject);
    setTimeout(() => {
      socket.terminate();
      reject(new Error(`${clientName} timed out`));
    }, 5000);
  });
}

const waitForServer = () => new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error(`server did not start\n${serverLog}`)), 5000);
  server.stdout.on('data', chunk => {
    if (String(chunk).includes('listening')) {
      clearTimeout(timer);
      resolve();
    }
  });
  server.stderr.on('data', chunk => {
    if (String(chunk).includes('server error')) {
      clearTimeout(timer);
      reject(new Error(serverLog));
    }
  });
});

(async () => {
  try {
    await waitForServer();
    const expected = [
      ['hello', 'collab-msg'],
      ['second client', 'ws 7.5.10'],
    ];
    const actual = await Promise.all(expected.map(messages => checkEcho('client', messages)));
    if (JSON.stringify(actual) !== JSON.stringify(expected)) {
      fail(`echo mismatch: ${JSON.stringify(actual)}`);
    }
    console.log(`PASS ${actual.flat().length} messages echoed across 2 handshakes`);
    console.log(serverLog.trim());
    server.kill('SIGTERM');
  } catch (error) {
    fail(error.stack || String(error));
  }
})();
